// The Dealshape logo: mark plus wordmark, from public/brand/wordmark.svg (generated by docs/brand/make_logo.py). Sizes in logo.js.
// BrandBlock (21 Oct): the logo with the tagline on its own line beneath, left-aligned with the wordmark's text. Used in every top bar.
import { NAME, TAGLINE } from "./brand.js";
import { TOP_BAR_LOGO_HEIGHT, logoSize, wordmarkTextOffset } from "./logo.js";

export default function Logo({ height = TOP_BAR_LOGO_HEIGHT }) {
  return <img className="brand-logo" src="/brand/wordmark.svg" alt={NAME} {...logoSize(height)} />;
}

export function BrandBlock({ className = "" }) {
  return (
    <span className={`brand-block ${className}`.trim()}>
      <Logo />
      <span className="brand-tagline" style={{ paddingLeft: wordmarkTextOffset(TOP_BAR_LOGO_HEIGHT) }}>{TAGLINE}</span>
    </span>
  );
}
